def locale_direction(code):
    return LOCALE_REGISTRY.get(code, ('', 'ltr'))[1] if isinstance(code, str) else 'ltr'

DEFAULT_LANGUAGE = 'en'
def workspace_settings(settings):
    """Discard obsolete presentation preferences without changing other settings."""
    return {key: value for key, value in settings.items()
            if key not in ('mode', 'show_sidebar_casual', 'show_sidebar')}


def safety_labels(ui, inspection):
    return '\n'.join(ui('safety_reason_' + m['label']) + (': ' + ', '.join(map(str,m['lines'])) if m['lines'] else '')
                     for m in inspection['matches'] if m['level'] == 'high')

def repeat_requires_confirmation(previous):
    """A deliberate Run suffices for a known successful repeat; uncertainty does not."""
    status = previous.get('status')
    if status in ('not_applicable', 'no_match'):
        return False
    return not (status == 'matched' and previous.get('process_exit') == '0'
                and previous.get('verdict') in ('PASS', 'NOT_REQUESTED')
                and not previous.get('reason') and not previous.get('reason_key'))

