def draft_catalogs():
    """Return independent draft catalogs for translation review; coverage does not imply activation."""
    result = {code: {} for code in _DRAFT_LOCALE_CODES}
    seen = set()
    for line in _DRAFT_ROWS.strip().splitlines():
        key, *values = line.split('|')
        if key in seen or key not in _MESSAGES['en'] or len(values) != len(result):
            raise ValueError('Invalid localization draft row: ' + key)
        seen.add(key)
        for code, value in zip(result, values):
            result[code][key] = value.replace(r'\n', '\n').replace(r'\x20', ' ')
    return result


def localization_draft_status(code, catalog):
    """Validate draft keys/format fields; never imply review or activation."""
    from collections import Counter
    from string import Formatter
    if code not in _DRAFT_LOCALE_CODES or not isinstance(catalog, dict):
        raise ValueError('Unknown draft locale or invalid catalog')
    english = _MESSAGES['en']
    def fields(text):
        return Counter((field, spec, conversion) for _, field, spec, conversion
                       in Formatter().parse(text) if field is not None)
    for key, value in catalog.items():
        if key not in english or not isinstance(value, str) or not value.strip():
            raise ValueError('Unknown or empty translation: ' + str(key))
        if fields(value) != fields(english[key]):
            raise ValueError('Format parameters changed: ' + key)
        if value.count('\n') != english[key].count('\n'):
            raise ValueError('Line structure changed: ' + key)
    missing = tuple(sorted(english.keys() - catalog.keys()))
    return {'language': code, 'direction': locale_direction(code),
            'translated': len(catalog), 'total': len(english), 'missing': missing,
            'catalog_complete': not missing, 'notice_reviewed': False,
            'editorial_reviewed': False, 'enabled': False}


