def _activate_preview_catalogs():
    """Only bundled, structurally complete catalogs with full notices enter preview."""
    drafts = draft_catalogs()
    for code, catalog in drafts.items():
        status = localization_draft_status(code, catalog)
        notice = _NOTICE_TRANSLATIONS.get(code, "")
        if not status["catalog_complete"] or len(notice.split("\n\n")) != 6 or not all(p.strip() for p in notice.split("\n\n")) or code not in _NOTICE_PREVIEW_LABELS:
            raise ValueError("Incomplete bundled preview locale: " + code)
    _MESSAGES.update(drafts)
    LANGUAGES.update({code: LOCALE_REGISTRY[code][0] for code in drafts})
    return frozenset(drafts)

PREVIEW_LANGUAGES = _activate_preview_catalogs()
